 let platformPulseRequest=null,platformPulseHasData=false,platformPulseLastUpdated='';
 async function refreshPlatformPulse(){
  const updated=$('#platformPulseUpdated'),health=$('#platformPulseHealth'),metrics=$('#platformPulseMetrics'),updates=$('#platformPulseUpdates'),trending=$('#platformPulseTrending'),refreshButton=$('#platformPulseRefresh');
  if(!metrics||!updates||!trending)return;
  if(platformPulseRequest)return platformPulseRequest;
  if(refreshButton){refreshButton.disabled=true;refreshButton.textContent='Refreshing…';refreshButton.dataset.inLangKey='Refreshing…'}setINLang(document.documentElement.lang||'en');
  if(updated)updated.textContent=platformPulseHasData?'Refreshing · last successful update '+platformPulseLastUpdated:'Refreshing real-time data…';if(!platformPulseHasData&&updated)updated.dataset.inLangKey='Refreshing real-time data…';setINLang(document.documentElement.lang||'en');
  if(!platformPulseHasData)metrics.setAttribute('aria-busy','true');
  platformPulseRequest=(async()=>{
   try{
    const [overviewResult,healthResult]=await Promise.allSettled([
     apiWithTimeout('/api/platform/overview',{},10000),
     apiWithTimeout('/api/health',{},10000)
    ]);
    if(healthResult.status==='fulfilled'){
     const service=healthResult.value||{},healthy=service.ok===true&&service.database===true;
     if(health){health.innerHTML=healthy?'<span data-in-lang-key="Operational · ">Operational · </span>'+esc(service.version||'version unknown'):'<span data-in-lang-key="Service issue · database unavailable">Service issue · database unavailable</span>';health.dataset.state=healthy?'healthy':'degraded';setINLang(document.documentElement.lang||'en')}
    }else if(health){health.innerHTML='<span data-in-lang-key="Health status unavailable">Health status unavailable</span>';health.dataset.state='unknown';setINLang(document.documentElement.lang||'en')}
    if(overviewResult.status!=='fulfilled')throw overviewResult.reason||new Error('The real-time overview could not be loaded.');
    const data=overviewResult.value,m=data?.metrics;
    const generatedAt=data.generated_at||data.asOf;if(!m||!generatedAt)throw new Error('The real-time overview response is incomplete.');
    const number=v=>{const n=Number(v);return Number.isFinite(n)&&n>=0?n.toLocaleString():'—'};
    const stamp=new Date(generatedAt);
    if(Number.isNaN(stamp.getTime()))throw new Error('The real-time overview timestamp is invalid.');
    platformPulseLastUpdated=stamp.toLocaleString([], {year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',timeZoneName:'short'});
    const metricCards=[
     ['Published novels',m.publishedNovels,'Eligible published novels in the catalog.'],
     ['Published chapters',m.publishedChapters,'Eligible published chapters in the catalog.'],
     ['Credited authors',m.creditedAuthors,'Distinct credited author names, not verified author accounts.'],
     ['Novel views · all-time',m.catalogViews,'Cumulative novel detail-page view counter. Repeat visits may count.'],
     ['Chapter views · all-time',m.chapterViews,'Cumulative chapter-reader requests. Repeat visits may count; not unique readers.'],
     ['Signed-in readers · 24h',m.readersInLast24Hours,'Distinct signed-in accounts with a reading-history update in the last 24 hours. Not current online users.'],
     ['Chapter updates · 24h',m.chapterUpdatesLast24Hours,'Published chapters edited or published in the last 24 hours.'],
     ['Visible comments',m.visibleComments,'Comments currently visible across eligible published novels.'],
     ['New comments · 24h',m.commentsLast24Hours,'Visible comments created in the last 24 hours.'],
     ['Comment likes',m.commentLikes,'Current likes on visible comments.'],
     ['Novel reactions',m.novelReactions,'Current reader reactions on novels.'],
     ['Reader ratings',m.ratings,'Current ratings recorded on published novels.'],
     ['Bookmarks',m.bookmarks,'Current chapter bookmarks recorded by readers.'],
     ['Novel follows',m.follows,'Current reader follows across published novels.']
    ];
    metrics.innerHTML=metricCards.map(([label,value,definition])=>'<div class="platformPulseMetric" title="'+esc(definition)+'"><b>'+number(value)+'</b><span data-in-lang-key="'+label+'">'+label+'</span></div>').join('');setINLang(document.documentElement.lang||'en');
    const rows=Array.isArray(data.recentUpdates)?data.recentUpdates:[];
    const validUpdates=rows.filter(row=>Number.isSafeInteger(Number(row.novel_id))&&Number(row.novel_id)>0&&Number.isSafeInteger(Number(row.chapter_number))&&Number(row.chapter_number)>0);
    updates.innerHTML=validUpdates.length?validUpdates.slice(0,6).map(row=>{const changedAt=row.updated_at?new Date(String(row.updated_at).replace(' ','T')+'Z'):null;const changedLabel=changedAt&&!Number.isNaN(changedAt.getTime())?changedAt.toLocaleString([], {dateStyle:'medium',timeStyle:'short',timeZone:'UTC'}):'Timestamp unavailable';return '<a class="platformPulseRow" href="/read/'+Number(row.novel_id)+'/'+Number(row.chapter_number)+'"><span><b>'+esc(row.novel_title)+'</b><small>Chapter '+Number(row.chapter_number)+' · '+esc(row.chapter_title)+' · Updated '+esc(changedLabel)+' UTC</small></span><span aria-hidden="true">↗</span></a>'}).join():'<p class="muted" data-in-lang-key="No published chapter updates are recorded yet.">No published chapter updates are recorded yet.</p>';
    const hot=Array.isArray(data.trending)?data.trending:[];
    const validHot=hot.filter(row=>Number.isSafeInteger(Number(row.id))&&Number(row.id)>0);
    trending.innerHTML=validHot.length?validHot.slice(0,5).map(row=>'<a class="platformPulseRow" href="/novel/'+Number(row.id)+'"><span><b>'+esc(row.title)+'</b><small>'+esc(row.author||'Imperial author')+'</small></span><span class="platformPulseCount">'+number(row.unlocksLast7Days)+' <span data-in-lang-key="unlocks">unlocks</span></span></a>').join():'<p class="muted" data-in-lang-key="No chapter unlock activity in the last seven days yet.">No chapter unlock activity in the last seven days yet.</p>';
    platformPulseHasData=true;
    metrics.setAttribute('aria-busy','false');
    if(updated)updated.textContent='Data generated '+platformPulseLastUpdated+' · refreshes every 60 seconds while this page is visible';setINLang(document.documentElement.lang||'en');
   }catch(error){
    metrics.setAttribute('aria-busy','false');
    if(platformPulseHasData){
     if(updated)updated.textContent='Refresh failed · showing last successful update '+platformPulseLastUpdated;
    }else{
     if(updated){updated.textContent='Real-time data temporarily unavailable';updated.dataset.inLangKey='Real-time data temporarily unavailable'}setINLang(document.documentElement.lang||'en');
     metrics.innerHTML='<div class="platformPulseError" role="status" data-in-lang-key="Real-time platform figures could not be loaded. Your catalog remains available.">Real-time platform figures could not be loaded. Your catalog remains available.</div>';
     updates.innerHTML='<p class="muted" data-in-lang-key="Update feed unavailable right now.">Update feed unavailable right now.</p>';
     trending.innerHTML='<p class="muted" data-in-lang-key="Trend data unavailable right now.">Trend data unavailable right now.</p>';setINLang(document.documentElement.lang||'en');
    }
   }finally{
    platformPulseRequest=null;
    if(refreshButton){refreshButton.disabled=false;refreshButton.textContent='Refresh ↻';delete refreshButton.dataset.inLangKey}setINLang(document.documentElement.lang||'en');
   }
  })();
  return platformPulseRequest;
 }
