 void refreshPlatformPulse();
 setInterval(()=>{if(document.visibilityState==='visible')refreshPlatformPulse()},60000);
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshPlatformPulse()});
