let novelEngagementRequest=null,novelEngagementLastUpdated='';
async function loadNovelEngagement(id){
 const metrics=$('#novelEngagementMetrics'),updated=$('#novelEngagementUpdated'),button=$('#novelEngagementRefresh');
 if(!metrics)return;
 if(novelEngagementRequest)return novelEngagementRequest;
 if(button)button.disabled=true;
 novelEngagementRequest=(async()=>{
  try{
   const data=await apiWithTimeout('/api/novel-engagement?novel_id='+encodeURIComponent(id),{},10000),m=data?.metrics;
   if(!m||!data.generated_at)throw new Error('Story activity response is incomplete.');
   const number=value=>{const n=Number(value);return Number.isFinite(n)&&n>=0?n.toLocaleString():'—'};
   const items=[['Novel views',m.novelViews],['Chapter views',m.chapterViews],['Comments',m.visibleComments],['Comment likes',m.commentLikes],['Novel reactions',m.novelReactions],['Ratings',m.ratings]];
   metrics.innerHTML=items.map(([label,value])=>'<div class="novelLivePulseMetric"><b>'+number(value)+'</b><span>'+label+'</span></div>').join('');
   const stamp=new Date(data.generated_at);if(Number.isNaN(stamp.getTime()))throw new Error('Story activity timestamp is invalid.');
   novelEngagementLastUpdated=stamp.toLocaleString([], {dateStyle:'medium',timeStyle:'medium'});
   if(updated)updated.textContent='Updated '+novelEngagementLastUpdated+' · 30-second refresh';
   const view=$('#novelViewCount');if(view)view.textContent=number(m.novelViews);
   metrics.setAttribute('aria-busy','false');
  }catch(error){
   metrics.setAttribute('aria-busy','false');
   if(updated)updated.textContent=novelEngagementLastUpdated?'Refresh failed · last update '+novelEngagementLastUpdated:'Story activity temporarily unavailable';
   if(!novelEngagementLastUpdated)metrics.innerHTML='<span class="muted" role="status">Reader activity is temporarily unavailable. Story reading remains available.</span>';
  }finally{
   novelEngagementRequest=null;if(button)button.disabled=false;
  }
 })();
 return novelEngagementRequest;
}
let imperialReactBundlePromise=null;
async function ensureImperialReactIslands(){
 if(window.ImperialReactIslands?.mountNovelReactions&&window.ImperialReactIslands?.mountNovelComments&&window.ImperialReactIslands?.mountNovelRating)return;
 if(!imperialReactBundlePromise){
  imperialReactBundlePromise=new Promise((resolve,reject)=>{
   const appScript=document.querySelector('script[src*="/app-"]');
   const appPath=appScript?.getAttribute("src")||"";
   const version=appPath.includes("app-")?appPath.slice(appPath.lastIndexOf("app-")+4).replace(".js",""):"17.20.0";
   const script=document.createElement("script");script.src="/react-islands-"+version+".js";script.async=true;
   script.onload=()=>window.ImperialReactIslands?.mountNovelReactions&&window.ImperialReactIslands?.mountNovelComments&&window.ImperialReactIslands?.mountNovelRating?resolve():reject(new Error("React community components did not initialize."));
   script.onerror=()=>reject(new Error("React community components could not be loaded."));
   document.head.appendChild(script);
  });
 }
 try{await imperialReactBundlePromise}catch(error){imperialReactBundlePromise=null;throw error}
}
