   analyticsChapters.innerHTML=data.chapters.length?data.chapters.slice(0,50).map(ch=>'<article class="authorAnalyticsChapter"><div><b>'+esc(ch.novelTitle)+' · Chapter '+numberFormat(ch.chapterNumber)+'</b><small>'+esc(ch.title||'Untitled chapter')+'</small></div><div class="authorAnalyticsChapterStats"><span>'+numberFormat(ch.chapterReaderRequests)+' lifetime requests</span><span>'+numberFormat(ch.chapterViewsInPeriod)+' period views</span><span>'+numberFormat(ch.unlocksInPeriod)+' unlocks</span><span>'+numberFormat(ch.readerTicketSpendInPeriod)+' ticket spend</span></div></article>').join(''):'<div class="empty">No published chapters have activity data yet.</div>';
  const timeline=data.timeline.slice(-14);
   analyticsTimeline.innerHTML=timeline.length?'<div class="authorAnalyticsDays">'+timeline.map(day=>'<div class="authorAnalyticsDay"><time>'+esc(String(day.day||'').slice(5))+'</time><b>'+numberFormat(Number(day.novelViews||0)+Number(day.chapterViews||0)+Number(day.unlocks||0)+Number(day.comments||0)+Number(day.commentLikes||0)+Number(day.reactions||0)+Number(day.follows||0))+'</b><small>'+numberFormat(day.novelViews)+' novel views · '+numberFormat(day.chapterViews)+' chapter views · '+numberFormat(day.unlocks)+' unlocks · '+numberFormat(day.comments)+' comments · '+numberFormat(day.commentLikes)+' likes · '+numberFormat(day.reactions)+' reactions · '+numberFormat(day.follows)+' follows</small></div>').join('')+'</div>':'<div class="empty">No timestamped reader activity in this period yet.</div>';
   const stamp=new Date(data.generated_at);analyticsUpdated.textContent='Updated '+(Number.isNaN(stamp.getTime())?'just now':stamp.toLocaleString([], {dateStyle:'medium',timeStyle:'medium'}))+' · refreshes every 60 seconds while visible';
