async function boot(){const root=document.querySelector('#app')||document.createElement('main');root.id='app';root.className='appBootRoot';root.innerHTML='<section class="bootFallback" role="status"><div class="bootCrest" aria-hidden="true">IN</div><p class="bootEyebrow">IMPERIAL NOVEL</p><h1>Your next world is loading.</h1><p>Preparing your storyverse…</p><span class="bootSpinner" aria-hidden="true"></span></section>';if(!document.body.contains(root))document.body.appendChild(root);try{shell();const p=location.pathname;const titles={'/':'Home','/discover':'Discover Novels & Stories','/community':'Reader Community','/leaderboard':'Story Rankings','/tier-list':'Story Tier Lists','/random':'Discover a Random Story','/made-for-you':'Stories Made for You','/for-you':'Stories Made for You','/trending':'Trending Stories','/vote':'Community Story Voting','/notifications':'Notifications','/settings':'Settings','/omniportal':'OmniPortal','/become-an-author':'Become an Author','/author':'Author Studio','/admin':'Command Center','/trend-factory':'Trend Factory'};if(titles[p])document.title=titles[p]+' | Imperial Novel';if(p==='/')await home();else if(p==='/trend-factory')await trendFactory();else if(p==='/discover'||p==='/catalog')await catalog();else if(p==='/formats')await formatDirectory();else if(/^\/format\/[^/]+\/?$/.test(p))await formatLanding(decodeURIComponent(p.split('/')[2]||''));else if(p==='/genres')await genres();else if(p==='/tags')await tags();else if(p==='/search')await search();else if(/^\/novel\/\d+\/chapters\/?$/.test(p))await chapters();else if(/^\/novel\/\d+\/?$/.test(p))await novel();else if(/^\/read\/\d+\/\d+\/?$/.test(p))await reader();else if(p==='/library')await library();else if(p==='/history')await history();else if(p==='/following')await following();else if(p==='/tickets')await tickets();else if(p==='/requests')await requests();else if(p==='/omniportal')await omni();else if(p==='/become-an-author')await becomeAuthor();else if(p==='/community')await discoveryPage('community');else if(p==='/leaderboard')await discoveryPage('leaderboard');else if(p==='/tier-list')await discoveryPage('tier-list');else if(p==='/random')await discoveryPage('random');else if(p==='/made-for-you'||p==='/for-you')await discoveryPage('made-for-you');else if(p==='/trending')await discoveryPage('trending');else if(p==='/vote')await discoveryPage('vote');else if(p==='/notifications')await discoveryPage('notifications');else if(p==='/settings')settings();else if(p==='/author')await authorStudio();else if(p==='/account')await account();else if(p==='/login')await authPage('login');else if(p==='/register')await authPage('register');else if(p.startsWith('/fandom/')){const slug=p.split('/').pop();location.href='/catalog?tag='+encodeURIComponent(slug)}else if(/^\/author\/[^/]+$/.test(p))await authorPublic();else simplePage('Page not found','The page you requested does not exist.');}catch(e){console.error('Imperial Novel boot failed',e);root.innerHTML=`<section class="bootFallback bootFailure" role="alert"><div class="bootCrest" aria-hidden="true">IN</div><p class="bootEyebrow">IMPERIAL NOVEL</p><h1>We hit a loading snag.</h1><p>${esc(e&&e.message||'The page could not finish loading.')}</p><button class="btn primary" onclick="location.reload()">Try again</button><p class="bootHelp">If this repeats, close this tab and reopen Imperial Novel.</p></section>`}}
boot();
